	avr_regbit_t	fe;			// frame error bit
	avr_regbit_t	dor;		// data overrun bit
	avr_regbit_t	upe;		// parity error bit
	avr_regbit_t	rxb8;		// receive data bit 8

	avr_regbit_t	ubrrl;
	avr_regbit_t	ubrrh;

	avr_int_vector_t rxc;
	avr_int_vector_t txc;
