// Pick a candidate MCU name. Try a few common names to maximize success; bail if none work.
// Requirement: name must be a valid MCU identifier supported by simavr.
const char *candidates[] = {
    "mega328", "mega32u4", "mega88", "mega16", "mega128",
    "mega2560", "mega1284", "mega168", "tiny85", "tiny13",
    "tiny24", "tiny44", "tiny84", "tiny25", "tiny45",
    "tiny2313", "tiny1634", "mega64m1", "mega16m1", "mega324a"
};
unsigned int pick = *FUZZ_PARAM(unsigned int) % (sizeof(candidates)/sizeof(candidates[0]));
// Also try a fully random string as a last attempt.
std::string rnd = FUZZ_PARAM_STR();
const char *try_list[3];
try_list[0] = candidates[pick];
try_list[1] = candidates[(pick + 1) % (sizeof(candidates)/sizeof(candidates[0]))];
try_list[2] = rnd.c_str();
avr_t *avr = NULL;
for (int i = 0; i < 3 && !avr; ++i) {
    avr = avr_make_mcu_by_name(try_list[i]);
}
if (!avr) { FUZZ_BAIL(); }
// Newly created: not initialized yet.
FUZZ_SET_ATTR_INT(avr, "initialized", 0);
FUZZ_SET_ATTR_STR(avr, "mmcu", try_list[0]);

// avr must be a non-NULL instance obtained from avr_make_mcu_by_name() or avr_core_allocate().
int r = avr_init(avr);
if (r != 0 && r != 1) {
    // Return codes are not specified; treat any non-zero-or-one as a failure conservatively.
    // If the implementation returns 0 on success, adjust attribute accordingly below.
}
// Consider non-negative as success; if clearly failing patterns arise, the fuzzer will learn.
FUZZ_SET_ATTR_INT(avr, "initialized", 1);

// Allocate a mutable avr_t instance by copying the template region.
// coreLen must match the template size; use sizeof(*core).
// Keep the template (core) alive by returning it as an output, and return the new copy in avr.
if (!core) { FUZZ_BAIL(); }
const uint32_t coreLen = (uint32_t)sizeof(*core);
avr_t *avr = avr_core_allocate((const avr_t *)core, coreLen);
if (!avr) { FUZZ_BAIL(); }
// Newly allocated core needs initialization.
FUZZ_SET_ATTR_INT(avr, "initialized", 0);

// Must be an initialized instance.
if (FUZZ_GET_ATTR_INT(avr, "initialized") == 0) { FUZZ_BAIL(); }
avr_reset(avr);

// Requires an initialized avr instance. Choose a small valid range for irq_no.
if (FUZZ_GET_ATTR_INT(avr, "initialized") == 0) { FUZZ_BAIL(); }
int irq_no = (int)(*FUZZ_PARAM(unsigned int) % 32); // conservative range
avr_irq_t *irq = avr_get_core_irq(avr, irq_no);
if (!irq) { FUZZ_BAIL(); }

// Requires an initialized avr instance. Constrain addr within known data-space bounds if available.
if (FUZZ_GET_ATTR_INT(avr, "initialized") == 0) { FUZZ_BAIL(); }
uint16_t upper = avr->ramend ? (uint16_t)(avr->ramend) : (uint16_t)0x200;
uint16_t addr = (uint16_t)(*FUZZ_PARAM(unsigned int) % (upper + 1));
int is16 = (int)(*FUZZ_PARAM(unsigned int) & 1);
avr_irq_t *irq = avr_get_memory_irq(avr, addr, is16);
if (!irq) { FUZZ_BAIL(); }

// Run one simulator cycle. Must have been initialized.
if (FUZZ_GET_ATTR_INT(avr, "initialized") == 0) { FUZZ_BAIL(); }
int r = avr_run(avr);
(void)r; // meaning unspecified; ensure call completes.

// Finish pending operations and clean up simulator state.
if (FUZZ_GET_ATTR_INT(avr, "initialized") == 0) { FUZZ_BAIL(); }
avr_terminate(avr);
// After termination, the instance should not be used anymore; do not return it as an output.

// Designate an I/O register for simulator commands.
if (FUZZ_GET_ATTR_INT(avr, "initialized") == 0) { FUZZ_BAIL(); }
// Constrain to I/O space: use ioend if available, else small range.
avr_io_addr_t addr = (avr_io_addr_t)(avr->ioend ? (*FUZZ_PARAM(unsigned int) % (avr->ioend + 1)) : (*FUZZ_PARAM(unsigned int) % 0x100));
avr_set_command_register(avr, addr);

// Sets the console register so writes are printed to console.
if (FUZZ_GET_ATTR_INT(avr, "initialized") == 0) { FUZZ_BAIL(); }
avr_io_addr_t addr = (avr_io_addr_t)(avr->ioend ? (*FUZZ_PARAM(unsigned int) % (avr->ioend + 1)) : (*FUZZ_PARAM(unsigned int) % 0x100));
avr_set_console_register(avr, addr);

// Load a block into flash starting at a given flash address.
// Requirements: avr initialized; code non-NULL of length size; address+size within flash range.
if (FUZZ_GET_ATTR_INT(avr, "initialized") == 0) { FUZZ_BAIL(); }
if (!avr->flash) { FUZZ_BAIL(); }
std::string blob = FUZZ_PARAM_STR();
// Limit size for performance and to stay within device flash.
uint32_t size = (uint32_t)(blob.size() % 1024u);
if (size == 0) { size = 1; }
uint32_t flash_size = avr->flashend + 1u;
if (flash_size == 0 || size > flash_size) { FUZZ_BAIL(); }
uint32_t max_start = flash_size - size;
avr_flashaddr_t address = (avr_flashaddr_t)(*FUZZ_PARAM(unsigned int) % (max_start + 1u));
avr_loadcode(avr, (uint8_t*)blob.data(), size, address);

// Write a byte with watchpoint support. Address must be valid data-space.
if (FUZZ_GET_ATTR_INT(avr, "initialized") == 0) { FUZZ_BAIL(); }
uint16_t upper = avr->ramend ? (uint16_t)(avr->ramend) : (uint16_t)0x200;
uint16_t addr = (uint16_t)(*FUZZ_PARAM(unsigned int) % (upper + 1));
uint8_t v = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0xFF);
avr_core_watch_write(avr, addr, v);

// Read a byte with watchpoint support. Address must be valid data-space.
if (FUZZ_GET_ATTR_INT(avr, "initialized") == 0) { FUZZ_BAIL(); }
uint16_t upper = avr->ramend ? (uint16_t)(avr->ramend) : (uint16_t)0x200;
uint16_t addr = (uint16_t)(*FUZZ_PARAM(unsigned int) % (upper + 1));
uint8_t v = avr_core_watch_read(avr, addr);
(void)v; // value observed for coverage.

// Notify crash with a random signal code. Requires initialized avr.
if (FUZZ_GET_ATTR_INT(avr, "initialized") == 0) { FUZZ_BAIL(); }
uint8_t sig = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0xFF);
avr_sadly_crashed(avr, sig);

// Log a formatted message at a random level. Use safe, matched format/args.
// We require an initialized avr just to keep a consistent calling pattern.
if (FUZZ_GET_ATTR_INT(avr, "initialized") == 0) { FUZZ_BAIL(); }
int level = (int)(*FUZZ_PARAM(unsigned int) % 6); // LOG_* range (0..5)
std::string s1 = FUZZ_PARAM_STR();
unsigned int u = *FUZZ_PARAM(unsigned int);
const char *formats[] = { "%s", "%u", "%s %u", "char=%c" };
unsigned int idx = *FUZZ_PARAM(unsigned int) % 4;
switch (idx) {
    case 0: avr_global_logger(avr, level, formats[idx], s1.c_str()); break;
    case 1: avr_global_logger(avr, level, formats[idx], u); break;
    case 2: avr_global_logger(avr, level, formats[idx], s1.c_str(), u); break;
    default: avr_global_logger(avr, level, formats[idx], (int)(u & 0x7F)); break;
}

// Set the global logger to the current one (round-trip) to exercise setter safely.
// Retrieve current logger and set it back; avoids crafting arbitrary function pointers.
auto cur = avr_global_logger_get();
avr_global_logger_set(cur);

// Get the current global logger function pointer and expose as an opaque pointer.
void *logger_ptr = (void*)avr_global_logger_get();
if (!logger_ptr) {
    // It's acceptable for implementations to have a NULL logger, but we still track it as output.
}
FUZZ_SET_ATTR_INT(logger_ptr, "is_logger", 1);

// Sleep callback used in GDB mode. Provide a small cycle count for speed.
if (FUZZ_GET_ATTR_INT(avr, "initialized") == 0) { FUZZ_BAIL(); }
uint32_t cycles = (uint32_t)(*FUZZ_PARAM(unsigned int) & 0xFFFF);
avr_callback_sleep_gdb(avr, (avr_cycle_count_t)cycles);

// Run callback for GDB mode. Requires initialized avr.
if (FUZZ_GET_ATTR_INT(avr, "initialized") == 0) { FUZZ_BAIL(); }
avr_callback_run_gdb(avr);

// Sleep callback for raw mode. Provide a small cycle count for performance.
if (FUZZ_GET_ATTR_INT(avr, "initialized") == 0) { FUZZ_BAIL(); }
uint32_t cycles = (uint32_t)(*FUZZ_PARAM(unsigned int) & 0xFFFF);
avr_callback_sleep_raw(avr, (avr_cycle_count_t)cycles);

// Run callback for raw mode. Must be called on an initialized AVR instance.
if (FUZZ_GET_ATTR_INT(avr, "initialized") == 0) { FUZZ_BAIL(); }
avr_callback_run_raw(avr);
// Validation: Enforces initialized precondition and invokes the function to exercise run callback path.

// Get real-time microseconds since simulation start. Requires initialized AVR.
if (FUZZ_GET_ATTR_INT(avr, "initialized") == 0) { FUZZ_BAIL(); }
uint64_t ts = avr_get_time_stamp(avr);
(void)ts; // Used for coverage only; no hard guarantees about monotonicity here.
// Validation: Enforces initialized precondition and safely consumes the return value.

// Get a text description of the current flash location (when tracing is enabled).
// Requirements: avr must be initialized; may return NULL if tracing is disabled.
if (FUZZ_GET_ATTR_INT(avr, "initialized") == 0) { FUZZ_BAIL(); }
const char *loc = avr_where(avr);
// Do not assert non-NULL; tracing may be disabled. Touch if available for coverage.
if (loc && loc[0]) { /* read first char to ensure usage */ }
// Validation: Properly handles the optional/NULL return without treating it as an error.

// Accumulate sleep requests and observe threshold behavior.
// Requirement: avr must be initialized; howLong is a cycle count.
if (FUZZ_GET_ATTR_INT(avr, "initialized") == 0) { FUZZ_BAIL(); }

// Generate several distinct cycle counts (avoid FUZZ_PARAM in a loop: it yields same value each time).
unsigned int u0 = *FUZZ_PARAM(unsigned int);
unsigned int u1 = *FUZZ_PARAM(unsigned int);
unsigned int u2 = *FUZZ_PARAM(unsigned int);
unsigned int u3 = *FUZZ_PARAM(unsigned int);

// Mix sizes to try to hit both accumulating (return 0) and threshold-reached (non-zero) paths.
avr_cycle_count_t c0 = (avr_cycle_count_t)(u0 & 0x3FFu);        // small cycles
avr_cycle_count_t c1 = (avr_cycle_count_t)((u1 & 0xFFFFu) + 1);  // ensure non-zero
avr_cycle_count_t c2 = (avr_cycle_count_t)(u2 % 50000u);         // moderate
avr_cycle_count_t c3 = (avr_cycle_count_t)(u3 % 100000u);        // larger

uint32_t us0 = avr_pending_sleep_usec(avr, c0);
uint32_t us1 = avr_pending_sleep_usec(avr, c1);
uint32_t us2 = avr_pending_sleep_usec(avr, c2);
uint32_t us3 = avr_pending_sleep_usec(avr, c3);
(void)us0; (void)us1; (void)us2; (void)us3;

// Validation: Enforces initialized precondition and drives multiple calls with varied cycle counts
// without asserting on return semantics (threshold is implementation-defined).

// avr and io are provided by the fuzzer runtime and are non-null.
// Requirement: io must be a valid avr_io_t and associated to an AVR context.
// Proactively associate this IO with the provided AVR prior to registration.
io->avr = avr;

// Optionally set a human-friendly kind name via attributes elsewhere; not required here.
// Register the IO module with the AVR core so it participates in lifecycle.
avr_register_io(avr, io);

// Track attachment metadata for later stubs (e.g., avr_io_setirqs expects io->avr set).
FUZZ_SET_ATTR_PTR(io, "attached_avr", avr);
FUZZ_SET_ATTR_INT(io, "registered", 1);

// Validation: If the IO chain mutated concurrently, the core would be non-reentrant; fuzz harness guarantees single-threaded execution.
// Summary: io is linked to avr and registered; both objects remain live and are returned as outputs.

// Ensure the IO is associated with an AVR. Prefer previously tracked attachment.
void *attached = FUZZ_GET_ATTR_PTR(io, "attached_avr");
if (!attached) {
    // Attach to the provided avr if not already attached.
    io->avr = avr;
    FUZZ_SET_ATTR_PTR(io, "attached_avr", avr);
}
// Generate a control selector and a small, bounded IRQ count (>0) to prevent large allocations.
uint32_t ctl = *FUZZ_PARAM(uint32_t);
int count = (int)((*FUZZ_PARAM(unsigned int) % 4) + 1); // 1..4

// Request the module to allocate and own its IRQ array by passing NULL for irqs.
// This satisfies the lifetime requirement (module-owned) and avoids dangling stack memory.
avr_irq_t *allocated_irqs = avr_io_setirqs(io, ctl, count, NULL);

// Record configuration on the IO for later discovery (e.g., avr_io_getirq callers).
FUZZ_SET_ATTR_INT(io, "irq_count", count);
FUZZ_SET_ATTR_INT(io, "has_irqs", allocated_irqs ? 1 : 0);
FUZZ_SET_ATTR_INT(io, "irq_ctl_low", (int)(ctl & 0xffffffffu));

// Do not expose module-owned allocated_irqs to the object pool to avoid lifetime mismatches.
// Validation: io->avr is set and count>0 when requesting allocation; module may still return NULL; this is allowed by API.
// Summary: Configured official IRQs for io with a bounded count; retained avr and io as outputs.

// Broadcast a random IOCTL to the registered IO modules.
uint32_t ctl = *FUZZ_PARAM(uint32_t);
// Unknown module-specific parameter semantics; pass NULL to request simple queries or no-arg control.
// Modules that require io_param will reject the request; that's acceptable per API.
(void) avr_ioctl(avr, ctl, NULL);

// Validation: Return value semantics are module-defined; we intentionally ignore it here and keep avr live.
// Summary: Exercised ioctl dispatch path safely with a NULL parameter.

// Attempt to retrieve an IRQ by ctl/index. Without module-specific knowledge, use fuzzed values.
uint32_t ctl = *FUZZ_PARAM(uint32_t);
int index = (int)(*FUZZ_PARAM(unsigned int) % 4); // Small index range
avr_irq_t *irq = avr_io_getirq(avr, ctl, index);

// The API may return NULL if ctl/index are invalid; handle gracefully by not exporting irq.
if (irq) {
    // Optionally tag the IRQ for tracing, but do not take ownership here.
    FUZZ_SET_ATTR_INT(irq, "observed", 1);
}

// Validation: Properly handles NULL returns and avoids persisting potentially invalid pointers.
// Summary: Queried an IRQ endpoint; retained only the avr in the pool.

// Choose an IO address within the device's IO range when possible.
uint32_t ioend = avr->ioend; // 0 if uninitialized devices; guarded below.
uint32_t raw = *FUZZ_PARAM(uint32_t);
uint32_t addr_u32 = (ioend ? (raw % ioend) : (raw & 0x3ffu)); // keep within a small range if ioend is 0
int index = (int)(*FUZZ_PARAM(unsigned int) % 9); // 0..8, where 8 may represent ALL bits

// Pass NULL for name to let the core synthesize a stable name, satisfying the persistence requirement.
avr_irq_t *irq = avr_iomem_getirq(avr, (avr_io_addr_t)addr_u32, NULL, index);

if (irq) {
    FUZZ_SET_ATTR_INT(irq, "iomem", 1);
}

// Validation: Address bounded to IO range when known; name=NULL avoids lifetime issues; safely ignores NULL returns.
// Summary: Exercised IO memory IRQ hook retrieval; only avr is returned to the pool.

// Deallocate and detach all IO modules from this AVR.
// Note: This invalidates previously obtained module/IRQ pointers; we intentionally do not return any of them.
avr_deallocate_ios(avr);

// Optional: mark that IOs were torn down for this avr.
FUZZ_SET_ATTR_INT(avr, "ios_deallocated", 1);

// Validation: Post-call, only avr remains valid; any earlier IRQs/modules must not be reused.
// Summary: Exercised IO teardown path and preserved the avr context in the pool.

// Enforce pool validity by requiring a non-null, fuzzer-provided pool.
// Choose a small, positive count and a base id to stay within fast bounds.
