import random
import string
from typing import List

# Target data type: plain text string (NUL-terminated when used in C++)
# We want to generate strings that are valid and interesting for the stubs:
# - avr_global_logger: used in printf formats %s and combined with %u; include
#   words, spaces, percent signs (but not unmatched format specifiers for our
#   generated strings because they are passed as %s argument), newlines.
# - avr_alloc_irq/init_irq: names array; include short, empty, and long tokens,
#   alphanumerics and symbols.
# - argv_parse: input line buffer to split into argv tokens; include spaces,
#   tabs, multiple consecutive delimiters, quoted sections, escaped spaces,
#   commas, semicolons, CR/LF, leading/trailing spaces, and empty tokens.
# - sim_setup_firmware: uses one FUZZ_PARAM_FILENAME (not produced here) and a
#   FUZZ_PARAM_STR as payload source; any non-empty string works.
# - hdump: prefix string; short readable prefix.
# - avr_vcd_add_signal: signal names; typical VCD names are word-like, but any
#   C-string is acceptable; include varying lengths and characters.
#
# Strategy:
# - Build a corpus of structured patterns: simple words, sentences, numeric,
#   hex-looking, CSV, shell-like command lines, quoted args, path-like, random
#   printable, and mixed unicode (UTF-8) where safe.
# - Randomly select and construct one pattern per call, with bounded length.
# - Ensure the result length <= 4096 bytes (we keep it much smaller).
# - Always return bytes (utf-8 encoded) without trailing NUL; the harness will
#   add as needed for C++ std::string.

MAX_LEN = 1024

UNICODE_FRAGMENTS = [
    "µ", "Ω", "Å", "é", "ß", "ñ", "中", "文", "日本語", "✓", "🚀"
]

WORDS = [
    "avr", "simavr", "logger", "irq", "pool", "vector", "firmware",
    "vcd", "signal", "uart", "spi", "twi", "timer", "watchdog",
    "init", "reset", "start", "stop", "enable", "disable", "read",
    "write", "compare", "overflow", "capture", "pending", "running"
]

PUNCT = "-_./:@#,+={}[]()"


def _rand_int(rng: random.Random, a: int, b: int) -> int:
    return rng.randint(a, b)


def _sample(rng: random.Random, seq: List[str], k: int) -> List[str]:
    if k <= 0:
        return []
    if k >= len(seq):
        return list(seq)
    return rng.sample(seq, k)


def _make_sentence(rng: random.Random) -> str:
    n = _rand_int(rng, 3, 12)
    toks = []
    for _ in range(n):
        w = rng.choice(WORDS)
        # occasionally append digits or punctuation
        if rng.random() < 0.4:
            w += str(_rand_int(rng, 0, 999))
        if rng.random() < 0.3:
            w += rng.choice(PUNCT)
        toks.append(w)
    s = " ".join(toks)
    if rng.random() < 0.5:
        s += rng.choice([".", "!", "?", "..."])
    return s


def _make_csv(rng: random.Random) -> str:
    cols = _rand_int(rng, 3, 8)
    parts = []
    for _ in range(cols):
        if rng.random() < 0.4:
            parts.append(f'"{_make_sentence(rng)}"')
        else:
            parts.append(_make_word(rng))
    return ",".join(parts)


def _make_word(rng: random.Random) -> str:
    L = _rand_int(rng, 2, 12)
    chars = string.ascii_letters + string.digits + PUNCT
    return "".join(rng.choice(chars) for _ in range(L))


def _make_shell_cmd(rng: random.Random) -> str:
    cmd = rng.choice(["avr-sim", "simavr", "run", "flash", "trace", "gdb"])
    args = []
    n = _rand_int(rng, 1, 8)
    for i in range(n):
        mode = _rand_int(rng, 0, 5)
        if mode == 0:
            args.append(f"--mcu={rng.choice(['atmega328p','atmega32u4','attiny85','mega2560'])}")
        elif mode == 1:
            args.append(f"--freq={_rand_int(rng,1,20)}MHz")
        elif mode == 2:
            # quoted arg with spaces
            args.append(f'--name="{_make_sentence(rng)}"')
        elif mode == 3:
            args.append(f"-v{_rand_int(rng,0,5)}")
        elif mode == 4:
            # path-like
            depth = _rand_int(rng, 1, 4)
            path = "/".join(_make_word(rng) for _ in range(depth))
            args.append(f"/tmp/{path}.hex")
        else:
            # escaped space
            args.append(_make_word(rng) + "\t" + _make_word(rng))
    line = " ".join([cmd] + args)
    # random CR/LF noise
    if rng.random() < 0.5:
        line = line + ("\r\n" if rng.random() < 0.5 else "\n")
    return line


def _make_random_printable(rng: random.Random, min_len=1, max_len=128) -> str:
    L = _rand_int(rng, min_len, max_len)
    chars = string.printable.replace("\x0b", "").replace("\x0c", "")
    return "".join(rng.choice(chars) for _ in range(L))


def _make_hexish(rng: random.Random) -> str:
    n = _rand_int(rng, 8, 64)
    return "".join(rng.choice("0123456789ABCDEF") for _ in range(n))


def _make_path_like(rng: random.Random) -> str:
    depth = _rand_int(rng, 1, 5)
    parts = [rng.choice(["/", "C:/"])[:-1]]  # base without trailing slash
    parts += [_make_word(rng) for _ in range(depth)]
    suf = rng.choice([".hex", ".elf", ".txt", ".log", ""])
    return "/".join(parts) + suf


def _make_vcd_signal_name(rng: random.Random) -> str:
    # typical VCD identifiers are word-ish; include hierarchies
    parts = _sample(rng, WORDS, _rand_int(rng, 1, 3))
    name = ".".join(parts)
    if rng.random() < 0.5:
        name += f"[{_rand_int(rng,0,31)}:{_rand_int(rng,0,31)}]"
    return name


def _make_argv_line(rng: random.Random) -> str:
    # Mix of tokens that argv_parse will split by spaces/tabs; include quotes
    tokens = []
    n = _rand_int(rng, 0, 10)
    for _ in range(n):
        tmode = _rand_int(rng, 0, 6)
        if tmode == 0:
            tokens.append(_make_word(rng))
        elif tmode == 1:
            tokens.append(f'"{_make_sentence(rng)}"')
        elif tmode == 2:
            tokens.append(_make_path_like(rng))
        elif tmode == 3:
            tokens.append("\\\"quoted\\\"")
        elif tmode == 4:
            tokens.append(_make_hexish(rng))
        elif tmode == 5:
            tokens.append(rng.choice([",", ";", ":"]))
        else:
            tokens.append(str(_rand_int(rng, 0, 100000)))
    sep_choices = [" ", "\t", "  ", " \t "]
    line = sep_choices[_rand_int(rng, 0, len(sep_choices)-1)].join(tokens)
    # Optional leading/trailing whitespace and CR/LF
    if rng.random() < 0.7:
        line = (" " * _rand_int(rng, 0, 3)) + line + (" " * _rand_int(rng, 0, 3))
    if rng.random() < 0.5:
        line += rng.choice(["\n", "\r\n", ""]) 
    return line


def _make_logger_message(rng: random.Random) -> str:
    # Keep % signs but avoid creating stray format specifiers that might confuse
    # logs elsewhere; they are passed as %s argument in the stub.
    base = _make_sentence(rng)
    inserts = ["%", "%%", "%done", "%level", "char=%c", "%u"]
    if rng.random() < 0.7:
        k = _rand_int(rng, 1, 3)
        for _ in range(k):
            pos = _rand_int(rng, 0, len(base))
            base = base[:pos] + " " + rng.choice(inserts) + " " + base[pos:]
    return base


def _make_payload(rng: random.Random) -> str:
    # For sim_setup_firmware payload source; any non-empty random string
    return _make_random_printable(rng, 8, 64)


def _maybe_unicode(rng: random.Random, s: str) -> str:
    if rng.random() < 0.4:
        frag = rng.choice(UNICODE_FRAGMENTS)
        pos = _rand_int(rng, 0, len(s))
        s = s[:pos] + frag + s[pos:]
    return s


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    pattern = rng.choice([
        "sentence", "csv", "shell", "printable", "hex", "path", "vcd",
        "argv", "logger", "payload"
    ])
    if pattern == "sentence":
        s = _make_sentence(rng)
    elif pattern == "csv":
        s = _make_csv(rng)
    elif pattern == "shell":
        s = _make_shell_cmd(rng)
    elif pattern == "printable":
        s = _make_random_printable(rng, 1, 256)
    elif pattern == "hex":
        s = _make_hexish(rng)
    elif pattern == "path":
        s = _make_path_like(rng)
    elif pattern == "vcd":
        s = _make_vcd_signal_name(rng)
    elif pattern == "argv":
        s = _make_argv_line(rng)
    elif pattern == "logger":
        s = _make_logger_message(rng)
    else:
        s = _make_payload(rng)

    s = _maybe_unicode(rng, s)

    # Truncate conservatively
    if len(s.encode('utf-8')) > MAX_LEN:
        # Rough truncation preserving UTF-8 validity by slicing on code points
        out = []
        total = 0
        for ch in s:
            b = ch.encode('utf-8')
            if total + len(b) > MAX_LEN:
                break
            out.append(ch)
            total += len(b)
        s = "".join(out)

    return s.encode('utf-8')
